const { vec } = NMath;
const K = 10;
const grid = 28;
const samples = await IO.loadMNIST();
if (samples.length < K) throw new Error("At least 10 MNIST images are required");

// An image is a density over the pixel grid: pixel (x, y) carries a mass equal to its intensity.
const positions = Array.from({ length: grid * grid }, (_, i) =>
    vec((i % grid + 0.5) / grid, 1 - (Math.floor(i / grid) + 0.5) / grid));
const toCloud = image => {
    const points = [], weights = [];
    image.components.forEach((value, i) => {
        if (value > 0) { points.push(positions[i]); weights.push(value); }
    });
    const total = weights.reduce((sum, w) => sum + w, 0);
    return { points, weights: weights.map(w => w / total) };
};
// 2-Wasserstein distance between two images.
const wasserstein = (a, b) =>
    OptimalTransport.wasserstein(toCloud(a), toCloud(b), { entropy: 0.01, maxIterations: 200 });

const kmeans = Kmeans.new(samples, K, { maxIterations: 5, distance: wasserstein }).fit();
const means = Array.from({ length: K }, () => new Float32Array(28 * 28));
const counts = new Array(K).fill(0);
for (const sample of samples) {
    const cluster = kmeans.predictIndex(sample);
    counts[cluster]++;
    for (let i = 0; i < sample.length; i++) means[cluster][i] += sample[i];
}
for (let cluster = 0; cluster < K; cluster++) {
    if (counts[cluster] === 0) {
        console.warn(`Cluster ${cluster} is empty`);
        continue;
    }
    for (let i = 0; i < means[cluster].length; i++) means[cluster][i] /= counts[cluster];
}
IO.paintMNIST(means, 5);
